import React, { useState } from "react";
import { searchMovies } from "../api/movieApi"; // 경로 조정 필요

const SearchPage = () => {
  const [query, setQuery] = useState("");
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");

  const handleSearch = async () => {
    if (!query.trim()) return;

    setLoading(true);
    setErrorMsg("");

    try {
      const results = await searchMovies(query);
      setMovies(results);
      if (results.length === 0) {
        setErrorMsg("검색 결과가 없습니다.");
      }
    } catch (error) {
      setErrorMsg("영화 검색에 실패했습니다.");
    } finally {
      setLoading(false);
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === "Enter") handleSearch();
  };

  return (
    <div className="p-4 max-w-xl mx-auto">
      <h1 className="text-2xl font-bold mb-4">🎥 영화 검색 (KOFIC)</h1>

      <div className="flex gap-2 mb-4">
        <input
          type="text"
          placeholder="영화 제목을 입력하세요"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={handleKeyDown}
          className="border rounded px-3 py-2 flex-1"
        />
        <button onClick={handleSearch} className="bg-blue-500 text-white px-4 py-2 rounded">
          검색
        </button>
      </div>

      {loading && <p>🔍 검색 중...</p>}
      {errorMsg && <p className="text-red-500">{errorMsg}</p>}

      <ul className="space-y-3">
        {movies.map((movie) => (
          <li key={movie.movieCd} className="border rounded p-3 shadow-sm">
            <h2 className="text-lg font-semibold">{movie.movieNm}</h2>
            <p>영문 제목: {movie.movieNmEn}</p>
            <p>제작연도: {movie.prdtYear}</p>
            <p>개봉일: {movie.openDt || "정보 없음"}</p>
            <p>감독: {movie.directors.map((d) => d.peopleNm).join(", ") || "정보 없음"}</p>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default SearchPage;
